package kanban;

import kanban.excecoes.LimiteWipException;
import kanban.excecoes.MovimentoInvalidoException;
import kanban.excecoes.TarefaNaoEncontradaException;
import kanban.modelo.Bug;
import kanban.modelo.Estimavel;
import kanban.modelo.Historia;
import kanban.modelo.Melhoria;
import kanban.modelo.Priorizavel;
import kanban.modelo.Status;
import kanban.modelo.Tarefa;
import kanban.quadro.Quadro;
import kanban.quadro.QuadroKanban;

public class Main {
    public static void main(String[] args) {
        Quadro quadro = new QuadroKanban(2);

        // Etapa 1: criar e editar tarefas
        Tarefa login = new Historia("Tela de login", 5);
        login.editarDescricao("Usuario entra com email e senha");
        quadro.adicionar(login);
        quadro.adicionar(new Bug("Botao salvar nao responde", 4));
        quadro.adicionar(new Melhoria("Deixar a busca mais rapida", 2, 3));
        quadro.adicionar(new Historia("Exportar relatorio", 8));
        exibir(quadro);

        // Etapa 2: mover tarefas pelas colunas
        tentarMover(quadro, 1, Status.FAZENDO);
        tentarMover(quadro, 2, Status.FAZENDO);
        tentarMover(quadro, 2, Status.FEITO);
        exibir(quadro);

        // Etapa 3: movimentos que devem falhar
        tentarMover(quadro, 4, Status.FEITO);
        tentarMover(quadro, 99, Status.FAZENDO);
        tentarMover(quadro, 3, Status.FAZENDO);
        tentarMover(quadro, 4, Status.FAZENDO);

        // Etapa 4: reabrir um bug, que so o Bug permite
        tentarMover(quadro, 1, Status.FEITO);
        tentarMover(quadro, 1, Status.FAZENDO);
        tentarMover(quadro, 2, Status.FAZENDO);
        exibir(quadro);

        // Etapa 5: titulo vazio e remocao
        try {
            new Bug("   ", 3);
        } catch (IllegalArgumentException e) {
            System.out.println("erro: " + e.getMessage());
        }
        try {
            quadro.remover(4);
            quadro.remover(4);
        } catch (TarefaNaoEncontradaException e) {
            System.out.println("erro: " + e.getMessage());
        }

        // Etapa 6: interfaces sem testar o tipo da tarefa
        resumo(quadro);
    }

    private static void tentarMover(Quadro quadro, int id, Status destino) {
        try {
            quadro.mover(id, destino);
            System.out.println("#" + id + " -> " + destino);
        } catch (TarefaNaoEncontradaException e) {
            System.out.println("erro: " + e.getMessage());
        } catch (LimiteWipException e) {
            System.out.println("erro de WIP: " + e.getMessage());
        } catch (MovimentoInvalidoException e) {
            System.out.println("erro: " + e.getMessage());
        }
    }

    private static void exibir(Quadro quadro) {
        System.out.println("==================================");
        for (Status status : Status.values()) {
            System.out.println(status);
            for (Tarefa tarefa : quadro.listar(status)) {
                System.out.println("  " + tarefa);
            }
        }
        System.out.println("==================================");
    }

    private static void resumo(Quadro quadro) {
        int pontos = 0;
        Priorizavel urgente = null;
        for (Status status : Status.values()) {
            for (Tarefa tarefa : quadro.listar(status)) {
                if (tarefa instanceof Estimavel e) {
                    pontos += e.getPontos();
                }
                if (tarefa instanceof Priorizavel p
                        && (urgente == null || p.getPrioridade() > urgente.getPrioridade())) {
                    urgente = p;
                }
            }
        }
        System.out.println("pontos no quadro: " + pontos);
        System.out.println("mais urgente: " + urgente);
    }
}

