package kanban.quadro;

import java.util.List;

import kanban.excecoes.MovimentoInvalidoException;
import kanban.excecoes.TarefaNaoEncontradaException;
import kanban.modelo.Status;
import kanban.modelo.Tarefa;

public interface Quadro {
    void adicionar(Tarefa tarefa);
    Tarefa buscar(int id) throws TarefaNaoEncontradaException;
    void mover(int id, Status destino) throws TarefaNaoEncontradaException, MovimentoInvalidoException;
    void remover(int id) throws TarefaNaoEncontradaException;
    List<Tarefa> listar(Status status);
}

