import java.util.List;

import kanban.excecoes.LimiteWipException;
import kanban.excecoes.MovimentoInvalidoException;
import kanban.excecoes.TarefaNaoEncontradaException;
import kanban.modelo.Bug;
import kanban.modelo.Estimavel;
import kanban.modelo.Historia;
import kanban.modelo.Melhoria;
import kanban.modelo.Priorizavel;
import kanban.modelo.Status;
import kanban.modelo.Tarefa;
import kanban.quadro.Quadro;
import kanban.quadro.QuadroKanban;

public class TesteDojo {
    interface Verificacao {
        void rodar() throws Exception;
    }

    static class Falha extends RuntimeException {
        Falha(String mensagem) {
            super(mensagem);
        }
    }

    static void checar(boolean condicao, String mensagem) {
        if (!condicao) {
            throw new Falha(mensagem);
        }
    }

    // Executa a acao e confere que ela lancou uma excecao do tipo esperado
    static void esperaExcecao(Class<?> tipo, Verificacao acao, String contexto) {
        try {
            acao.rodar();
        } catch (Exception e) {
            checar(tipo.isInstance(e), contexto + " lancou " + e.getClass().getSimpleName() + ", mas devia lancar " + tipo.getSimpleName());
            return;
        }
        throw new Falha(contexto + " devia lancar " + tipo.getSimpleName() + ", mas nao lancou nada");
    }

    static void teste(String nome, Verificacao v) {
        try {
            v.rodar();
            System.out.println("OK|" + nome);
        } catch (Falha f) {
            System.out.println("FALHA|" + nome + "|" + f.getMessage());
        } catch (Throwable t) {
            System.out.println("FALHA|" + nome + "|excecao inesperada " + t);
        }
    }

    static Tarefa andar(Tarefa t, Status... caminho) throws Exception {
        for (Status s : caminho) {
            t.mover(s);
        }
        return t;
    }

    public static void main(String[] args) {
        teste("Tarefa nova comeca em A_FAZER", () -> {
            checar(new Historia("Login", 3).getStatus() == Status.A_FAZER, "o status inicial nao e A_FAZER");
        });
        teste("Cada tarefa recebe um id diferente e crescente", () -> {
            Tarefa a = new Bug("A", 1), b = new Historia("B", 1), c = new Melhoria("C", 1, 1);
            checar(a.getId() < b.getId() && b.getId() < c.getId(), "ids " + a.getId() + ", " + b.getId() + ", " + c.getId());
        });
        teste("Construtor guarda o titulo", () -> {
            checar("Tela de login".equals(new Historia("Tela de login", 5).getTitulo()), "getTitulo devolveu outro texto");
        });
        teste("editarTitulo e editarDescricao mudam os dados", () -> {
            Tarefa t = new Bug("Antigo", 2);
            t.editarTitulo("Novo");
            t.editarDescricao("Detalhes");
            checar("Novo".equals(t.getTitulo()), "o titulo nao mudou");
            checar("Detalhes".equals(t.getDescricao()), "a descricao nao mudou");
        });
        teste("Titulo vazio lanca IllegalArgumentException", () -> {
            esperaExcecao(IllegalArgumentException.class, () -> new Historia("", 1), "new Historia(\"\", 1)");
            esperaExcecao(IllegalArgumentException.class, () -> new Bug("   ", 1), "new Bug(\"   \", 1)");
            Tarefa t = new Melhoria("Ok", 1, 1);
            esperaExcecao(IllegalArgumentException.class, () -> t.editarTitulo(""), "editarTitulo(\"\")");
            checar("Ok".equals(t.getTitulo()), "o titulo mudou mesmo com a excecao");
        });
        teste("Cada tipo tem um getTipo diferente", () -> {
            String b = new Bug("x", 1).getTipo(), h = new Historia("x", 1).getTipo(), m = new Melhoria("x", 1, 1).getTipo();
            checar(b != null && h != null && m != null, "getTipo devolveu null");
            checar(!b.equals(h) && !b.equals(m) && !h.equals(m), "tipos repetidos: " + b + ", " + h + ", " + m);
        });
        teste("Bug e Melhoria sao Priorizavel", () -> {
            Object b = new Bug("x", 4), m = new Melhoria("x", 2, 3);
            checar(b instanceof Priorizavel && m instanceof Priorizavel, "falta implements Priorizavel");
            checar(((Priorizavel) b).getPrioridade() == 4, "a prioridade do Bug devia ser a severidade");
            checar(((Priorizavel) m).getPrioridade() == 2, "a prioridade da Melhoria esta errada");
        });
        teste("Historia e Melhoria sao Estimavel", () -> {
            Object h = new Historia("x", 8), m = new Melhoria("x", 2, 3);
            checar(h instanceof Estimavel && m instanceof Estimavel, "falta implements Estimavel");
            checar(((Estimavel) h).getPontos() == 8 && ((Estimavel) m).getPontos() == 3, "getPontos devolveu outro valor");
            checar(!(h instanceof Priorizavel), "Historia nao devia ser Priorizavel");
        });
        teste("Movimentos permitidos", () -> {
            Tarefa t = andar(new Historia("x", 1), Status.FAZENDO, Status.A_FAZER, Status.FAZENDO, Status.FEITO);
            checar(t.getStatus() == Status.FEITO, "a tarefa nao terminou em FEITO");
        });
        teste("Pular de A_FAZER para FEITO e proibido", () -> {
            Tarefa t = new Historia("x", 1);
            esperaExcecao(MovimentoInvalidoException.class, () -> t.mover(Status.FEITO), "mover(FEITO) a partir de A_FAZER");
            checar(t.getStatus() == Status.A_FAZER, "o status mudou mesmo com a excecao");
        });
        teste("Mover para o mesmo status e proibido", () -> {
            Tarefa t = new Melhoria("x", 1, 1);
            esperaExcecao(MovimentoInvalidoException.class, () -> t.mover(Status.A_FAZER), "mover(A_FAZER) a partir de A_FAZER");
        });
        teste("Historia em FEITO nao volta", () -> {
            Tarefa t = andar(new Historia("x", 1), Status.FAZENDO, Status.FEITO);
            esperaExcecao(MovimentoInvalidoException.class, () -> t.mover(Status.FAZENDO), "Historia mover(FAZENDO) a partir de FEITO");
            checar(t.getStatus() == Status.FEITO, "o status mudou mesmo com a excecao");
        });
        teste("Bug em FEITO pode ser reaberto", () -> {
            Tarefa t = andar(new Bug("x", 3), Status.FAZENDO, Status.FEITO, Status.FAZENDO);
            checar(t.getStatus() == Status.FAZENDO, "o Bug nao voltou para FAZENDO");
            Tarefa b = andar(new Bug("y", 3), Status.FAZENDO, Status.FEITO);
            esperaExcecao(MovimentoInvalidoException.class, () -> b.mover(Status.A_FAZER), "Bug mover(A_FAZER) a partir de FEITO");
        });
        teste("Quadro busca a tarefa pelo id", () -> {
            Quadro q = new QuadroKanban(3);
            Tarefa a = new Bug("a", 1), b = new Historia("b", 2);
            q.adicionar(a);
            q.adicionar(b);
            checar(q.buscar(b.getId()) == b && q.buscar(a.getId()) == a, "buscar devolveu outra tarefa");
            esperaExcecao(TarefaNaoEncontradaException.class, () -> q.buscar(-1), "buscar(-1)");
        });
        teste("Quadro lista por status na ordem em que as tarefas entraram", () -> {
            Quadro q = new QuadroKanban(3);
            Tarefa a = new Bug("a", 1), b = new Historia("b", 2), c = new Melhoria("c", 1, 1);
            q.adicionar(a);
            q.adicionar(b);
            q.adicionar(c);
            q.mover(b.getId(), Status.FAZENDO);
            List<Tarefa> aFazer = q.listar(Status.A_FAZER), fazendo = q.listar(Status.FAZENDO), feito = q.listar(Status.FEITO);
            checar(aFazer.size() == 2 && aFazer.get(0) == a && aFazer.get(1) == c, "A_FAZER devia ter a e c, nessa ordem");
            checar(fazendo.size() == 1 && fazendo.get(0) == b, "FAZENDO devia ter so b");
            checar(feito.isEmpty(), "FEITO devia estar vazia");
        });
        teste("Quadro move pelo id e respeita as regras da tarefa", () -> {
            Quadro q = new QuadroKanban(3);
            Tarefa a = new Historia("a", 1);
            q.adicionar(a);
            esperaExcecao(MovimentoInvalidoException.class, () -> q.mover(a.getId(), Status.FEITO), "quadro.mover pulando FAZENDO");
            esperaExcecao(TarefaNaoEncontradaException.class, () -> q.mover(-1, Status.FAZENDO), "quadro.mover(-1, ...)");
        });
        teste("Remover tira a tarefa do quadro", () -> {
            Quadro q = new QuadroKanban(3);
            Tarefa a = new Bug("a", 1);
            q.adicionar(a);
            q.remover(a.getId());
            checar(q.listar(Status.A_FAZER).isEmpty(), "a tarefa continua na lista");
            esperaExcecao(TarefaNaoEncontradaException.class, () -> q.buscar(a.getId()), "buscar depois de remover");
            esperaExcecao(TarefaNaoEncontradaException.class, () -> q.remover(a.getId()), "remover duas vezes");
        });
        teste("Limite de WIP em FAZENDO", () -> {
            Quadro q = new QuadroKanban(2);
            Tarefa a = new Bug("a", 1), b = new Bug("b", 1), c = new Bug("c", 1);
            q.adicionar(a);
            q.adicionar(b);
            q.adicionar(c);
            q.mover(a.getId(), Status.FAZENDO);
            q.mover(b.getId(), Status.FAZENDO);
            esperaExcecao(LimiteWipException.class, () -> q.mover(c.getId(), Status.FAZENDO), "terceira tarefa em FAZENDO com limite 2");
            checar(c.getStatus() == Status.A_FAZER, "a tarefa entrou em FAZENDO mesmo passando do limite");
            q.mover(a.getId(), Status.FEITO);
            q.mover(c.getId(), Status.FAZENDO);
            checar(c.getStatus() == Status.FAZENDO, "depois de liberar uma vaga a tarefa devia entrar");
        });
        teste("LimiteWipException e um MovimentoInvalidoException", () -> {
            Exception e = new LimiteWipException(1);
            checar(e instanceof MovimentoInvalidoException, "LimiteWipException devia herdar de MovimentoInvalidoException");
        });
        teste("Excecoes do quadro sao verificadas", () -> {
            checar(!RuntimeException.class.isAssignableFrom(TarefaNaoEncontradaException.class), "TarefaNaoEncontradaException herda de RuntimeException");
            checar(!RuntimeException.class.isAssignableFrom(MovimentoInvalidoException.class), "MovimentoInvalidoException herda de RuntimeException");
        });
    }
}

