package juiz;

import java.util.List;

import kanban.modelo.Bug;
import kanban.modelo.Estimavel;
import kanban.modelo.Historia;
import kanban.modelo.Melhoria;
import kanban.modelo.Priorizavel;
import kanban.modelo.Status;
import kanban.modelo.Tarefa;
import kanban.quadro.Quadro;
import kanban.quadro.QuadroKanban;

/** Liga o quadro visual do site ao código dos alunos, usando só os métodos do diagrama.
 *  Cada comando chega como campos separados por \u0001 e a resposta é o estado do quadro em JSON. */
public class Ponte {
    private final Quadro quadro;

    public Ponte(int limiteFazendo) {
        quadro = new QuadroKanban(limiteFazendo);
    }

    public String comando(String linha) {
        String[] c = linha.split("\u0001", -1);
        String erro = null;
        Guard.deadline = System.currentTimeMillis() + 2000;
        try {
            switch (c[0]) {
                case "nova":
                    Tarefa t;
                    if (c[1].equals("BUG")) {
                        t = new Bug(c[2], Integer.parseInt(c[3]));
                    } else if (c[1].equals("HISTORIA")) {
                        t = new Historia(c[2], Integer.parseInt(c[4]));
                    } else {
                        t = new Melhoria(c[2], Integer.parseInt(c[3]), Integer.parseInt(c[4]));
                    }
                    if (!c[5].isEmpty()) {
                        t.editarDescricao(c[5]);
                    }
                    quadro.adicionar(t);
                    break;
                case "mover":
                    quadro.mover(Integer.parseInt(c[1]), Status.valueOf(c[2]));
                    break;
                case "titulo":
                    quadro.buscar(Integer.parseInt(c[1])).editarTitulo(c[2]);
                    break;
                case "descricao":
                    quadro.buscar(Integer.parseInt(c[1])).editarDescricao(c[2]);
                    break;
                case "remover":
                    quadro.remover(Integer.parseInt(c[1]));
                    break;
                default:
                    break;
            }
        } catch (Throwable e) {
            erro = descrever(e);
        } finally {
            Guard.deadline = Long.MAX_VALUE;
        }
        return "{\"erro\":" + json(erro) + ",\"colunas\":" + estado() + "}";
    }

    private static String descrever(Throwable e) {
        if (e instanceof JuizTimeout) {
            return "Tempo limite excedido, algum método entrou em laço infinito";
        }
        String msg = e.getMessage();
        return e.getClass().getSimpleName() + (msg == null ? "" : ": " + msg);
    }

    private String estado() {
        StringBuilder sb = new StringBuilder("{");
        Guard.deadline = System.currentTimeMillis() + 2000;
        try {
            for (Status s : Status.values()) {
                if (sb.length() > 1) {
                    sb.append(',');
                }
                sb.append(json(s.name())).append(":[");
                List<Tarefa> lista = quadro.listar(s);
                for (int i = 0; lista != null && i < lista.size(); i++) {
                    if (i > 0) {
                        sb.append(',');
                    }
                    sb.append(cartao(lista.get(i)));
                }
                sb.append(']');
            }
            return sb.append('}').toString();
        } catch (Throwable e) {
            return "{\"falha\":" + json("listar falhou com " + descrever(e)) + "}";
        } finally {
            Guard.deadline = Long.MAX_VALUE;
        }
    }

    private static String cartao(Tarefa t) {
        StringBuilder sb = new StringBuilder("{");
        sb.append("\"id\":").append(t.getId());
        sb.append(",\"tipo\":").append(json(t.getTipo()));
        sb.append(",\"classe\":").append(json(t.getClass().getSimpleName()));
        sb.append(",\"titulo\":").append(json(t.getTitulo()));
        sb.append(",\"descricao\":").append(json(t.getDescricao()));
        sb.append(",\"status\":").append(json(String.valueOf(t.getStatus())));
        if (t instanceof Priorizavel p) {
            sb.append(",\"prioridade\":").append(p.getPrioridade());
        }
        if (t instanceof Estimavel e) {
            sb.append(",\"pontos\":").append(e.getPontos());
        }
        return sb.append('}').toString();
    }

    private static String json(String s) {
        if (s == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder("\"");
        for (char ch : s.toCharArray()) {
            if (ch == '"' || ch == '\\') {
                sb.append('\\').append(ch);
            } else if (ch < 0x20) {
                sb.append(String.format("\\u%04x", (int) ch));
            } else {
                sb.append(ch);
            }
        }
        return sb.append('"').toString();
    }
}
